mapper.select:
        select
        wmr.*
        FROM wms_material_returnable wmr
        left join wms_outbound wo on wmr.outbound_id = wo.id
        where
        wmr.bool_delete_enum = 0
        and  wmr.bool_return = 1
        
            and wo.outbound_type_selection = #{outboundTypeSelection}
        
        
            and wmr.material_is_whole = #{materialIsWhole}
        
        
            and wmr.basic_class = #{basicClass}
        
        
            and wmr.classify_id = #{classifyId}
        
        
            and wmr.workshop_id = #{workshopId}
        
        
            and wmr.warehouse_id = #{warehouseId}
        
        
            AND wmr.specification like CONCAT('%', #{specification},'%')
        
        
            AND wmr.quantity > #{minLength}
        
        
            AND wmr.quantity < #{maxLength}
        
        
            AND wmr.length = #{length}
        
        
            AND wmr.width = #{width}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and wmr.quantity >= #{minLength}
        
        
            and wmr.quantity <= #{maxLength}
        

        
            AND wmr.theory_thickness = #{theoryThickness}
        
        
            AND wmr.thickness = #{thickness}
        
        
            AND wmr.project_id = #{projectId}
        
        
            AND wmr.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wmr.color like CONCAT('%', #{color},'%')
        
        
            AND wmr.brand like CONCAT('%', #{brand},'%')
        
        
            and wmr.workshop_id=#{workshopId}
        
        
            and wmr.classify_id in
            
                #{item}
            
        
        
            and wmr.classify_id = #{classifyId}
        
        
            
                -- 开始时间: 数据 大于 条件
                and wmr.outbound_time > #{createTime[0]}
            
            
                -- 结束时间: 数据 小于 条件
                and wmr.outbound_time < #{createTime[1]}
            
        
        
            and wmr.single_returnable_mete >#{mete}
        
        
            and wmr.bool_party_a =#{boolPartyA}
        
        
            AND wo.serial_number like CONCAT('%', #{serialNumber},'%')
        
          -- app拍照退库查询时 不查有审核中退库单的 pc端是前端限制的
        
            AND wmr.bool_review_pending =#{boolReviewPending}
        
        
            and wmr.area_batch_id = #{areaBatchId}
        
        
            and wmr.recipient_id = #{recipientId}

        select
        *
        FROM wms_material_returnable
        where
        bool_delete_enum = 0
        and  bool_return = 1
        
            and material_is_whole = #{materialIsWhole}
        
        
            and basic_class = #{basicClass}
        
        
            and classify_id = #{classifyId}
        
        
            and workshop_id = #{workshopId}
        
        
            and warehouse_id = #{warehouseId}
        
        
            AND specification like CONCAT('%', #{specification},'%')
        
        
            AND quantity > #{minLength}
        
        
            AND quantity < #{maxLength}
        
        
            AND length = #{length}
        
        
            AND width = #{width}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and quantity >= #{minLength}
        
        
            and quantity <= #{maxLength}
        

        
            AND theory_thickness = #{theoryThickness}
        
        
            AND thickness = #{thickness}
        
        
            AND project_id = #{projectId}
        
        
            AND heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND color like CONCAT('%', #{color},'%')
        
        
            AND brand like CONCAT('%', #{brand},'%')
        
        
            and workshop_id=#{workshopId}
        
        
            and classify_id in
            
                #{item}
            
        
        
            and classify_id = #{classifyId}
        
        
            
                -- 开始时间: 数据 大于 条件
                and outbound_time > #{createTime[0]}
            
            
                -- 结束时间: 数据 小于 条件
                and outbound_time < #{createTime[1]}
            
        
        --可退库出库单类型
        
            and outbound_type_selection = #{outboundTypeSelection}
